$note = Get-Content data\challenge-notes-private.json -Raw; \ = \False; Get-ChildItem public -Recurse -File | Where-Object { \.Extension -match '\.(html|js|json|css|txt|md)$' -and \.FullName -notlike '*challenge-notes-private*' } | ForEach-Object { try { \ = Get-Content \.FullName -Raw; if (\.Length -gt 0 -and \.Length -gt 30 -and \.IndexOf(\.Substring(0,30)) -ge 0) { \ = \True } } catch {} }; if (\) { Write-Host 'FOUND' } else { Write-Host 'OK' }
